    void remove_selected(){std::vector<browser_library::Entry> selected;for(const auto& value:list_.SelectedItems()){std::uint32_t index{};if(list_.Items().IndexOf(value,index)&&index<shown_.size())selected.push_back(shown_[index]);}if(selected.empty())return;const bool history=mode_.SelectedIndex()==1;work([selected=std::move(selected),history](auto& contents){for(const auto& item:selected){if(history)browser_library::Store::remove_history(contents,item.url);else std::erase_if(contents.bookmarks,[&](const auto& entry){return entry.id==item.id;});}},true,"Selected items removed.");}
